* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', 'Oxygen',
    'Ubuntu', 'Cantarell', 'Fira Sans', 'Droid Sans', 'Helvetica Neue',
    sans-serif;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  background: linear-gradient(135deg, #f5f7fa 0%, #c3cfe2 100%);
  color: #333;
  line-height: 1.6;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

/* Skip link */
.skip-link a {
  position: absolute;
  top: -40px;
  left: 0;
  background: #000;
  color: #fff;
  padding: 8px 16px;
  text-decoration: none;
  z-index: 100;
  border-radius: 0 0 4px 0;
}

.skip-link a:focus {
  top: 0;
}

/* Header */
.header {
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  color: white;
  padding: 3rem 2rem;
  text-align: center;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
}

.header-content h1 {
  font-size: 2.5rem;
  margin-bottom: 0.5rem;
  font-weight: 700;
}

.header-content p {
  font-size: 1.1rem;
  opacity: 0.95;
  font-weight: 300;
}

/* Main content */
.main {
  flex: 1;
  max-width: 900px;
  width: 100%;
  margin: 0 auto;
  padding: 2rem;
}

.faq-container {
  background: white;
  border-radius: 12px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.1);
  padding: 2rem;
  overflow: hidden;
}

.section-title {
  font-size: 1.8rem;
  margin-bottom: 2rem;
  color: #667eea;
  font-weight: 600;
  text-align: center;
}

.faq-list {
  display: flex;
  flex-direction: column;
  gap: 0;
}

/* FAQ Item wrapper */
.example {
  border-bottom: 1px solid #e8eef5;
  transition: background-color 0.2s ease;
}

.example:last-child {
  border-bottom: none;
}

.example:hover {
  background-color: #f8f9fc;
}

/* FAQ heading */
.faq-heading {
  margin: 0;
  padding: 0;
}

/* FAQ trigger button */
.faq-trigger {
  width: 100%;
  padding: 1.25rem 1.5rem;
  text-align: left;
  background: none;
  border: none;
  font-size: 1rem;
  font-weight: 600;
  color: #333;
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
  transition: color 0.2s ease;
  position: relative;
}

.faq-trigger:hover {
  color: #667eea;
}

.faq-trigger:focus {
  outline: none;
  background-color: #f0f4ff;
  color: #667eea;
}

.faq-trigger::after {
  content: '▼';
  font-size: 0.75rem;
  margin-left: 1rem;
  flex-shrink: 0;
  transition: transform 0.3s ease;
  color: #667eea;
}

.faq-trigger[aria-expanded="true"]::after {
  transform: rotate(-180deg);
}

/* Focus indicator */
.faq-trigger:focus-visible {
  outline: 2px solid #667eea;
  outline-offset: -2px;
  box-shadow: inset 0 0 0 2px white;
}

/* FAQ answer content */
.details {
  padding: 0 1.5rem 1.25rem 1.5rem;
  overflow: hidden;
  animation: slideDown 0.3s ease;
}

.details p {
  color: #555;
  margin: 0;
  font-size: 0.95rem;
  line-height: 1.7;
}

.details p + p {
  margin-top: 1rem;
}

@keyframes slideDown {
  from {
    opacity: 0;
    max-height: 0;
  }
  to {
    opacity: 1;
    max-height: 500px;
  }
}

/* Footer */
.footer {
  background-color: #2d3748;
  color: #a0aec0;
  text-align: center;
  padding: 2rem;
  font-size: 0.9rem;
}

.footer p {
  margin: 0;
}

/* Responsive design */
@media (max-width: 768px) {
  .header-content h1 {
    font-size: 2rem;
  }

  .header-content p {
    font-size: 1rem;
  }

  .main {
    padding: 1rem;
  }

  .faq-container {
    padding: 1.5rem;
  }

  .section-title {
    font-size: 1.5rem;
    margin-bottom: 1.5rem;
  }

  .faq-trigger {
    padding: 1rem 1rem;
    font-size: 0.95rem;
  }

  .details {
    padding: 0 1rem 1rem 1rem;
  }

  .details p {
    font-size: 0.9rem;
  }
}

@media (max-width: 480px) {
  body {
    background: linear-gradient(135deg, #f5f7fa 0%, #c3cfe2 100%);
  }

  .header-content h1 {
    font-size: 1.5rem;
  }

  .header-content p {
    font-size: 0.9rem;
  }

  .faq-container {
    border-radius: 8px;
    padding: 1rem;
  }

  .section-title {
    font-size: 1.25rem;
    margin-bottom: 1rem;
  }

  .faq-trigger {
    padding: 0.875rem 0.875rem;
    font-size: 0.9rem;
  }

  .faq-trigger::after {
    font-size: 0.65rem;
    margin-left: 0.75rem;
  }

  .details {
    padding: 0 0.875rem 0.875rem 0.875rem;
  }

  .details p {
    font-size: 0.85rem;
  }
}

/* High contrast mode support */
@media (prefers-contrast: more) {
  .faq-trigger {
    color: #000;
    font-weight: 700;
  }

  .faq-trigger:hover {
    color: #667eea;
    text-decoration: underline;
  }

  .faq-trigger::after {
    color: #000;
  }

  .details p {
    color: #000;
  }
}

/* Reduced motion support */
@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

/* Forced colors mode (Windows High Contrast) */
@media (forced-colors: active) {
  .faq-trigger {
    forced-color-adjust: none;
    border: 1px solid transparent;
  }

  .faq-trigger:focus-visible {
    outline-width: 2px;
  }

  .header {
    forced-color-adjust: none;
  }

  .faq-container {
    border: 1px solid CanvasText;
  }
}
