  overflow: hidden;
}

.section-title {
  font-size: 1.8rem;
  margin-bottom: 2rem;
  color: #667eea;
  font-weight: 600;
  text-align: center;
}

.faq-list {
  display: flex;
  flex-direction: column;
  gap: 0;
}

/* FAQ Item wrapper */
.example {
  border-bottom: 1px solid #e8eef5;
  transition: background-color 0.2s ease;
}

.example:last-child {
  border-bottom: none;
}

.example:hover {
  background-color: #f8f9fc;
}

/* FAQ heading */
.faq-heading {
  margin: 0;
  padding: 0;
}

/* FAQ trigger button */
.faq-trigger {
  width: 100%;
  padding: 1.25rem 1.5rem;
  text-align: left;
  background: none;
  border: none;
  font-size: 1rem;
  font-weight: 600;
  color: #333;
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
  transition: color 0.2s ease;
  position: relative;
}

.faq-trigger:hover {
  color: #667eea;
