document.addEventListener('DOMContentLoaded', () => {
  const triggers = document.querySelectorAll('.faq-trigger');

  triggers.forEach((btn) => {
    // Get the panel (next sibling with class "details")
    const panel = btn.closest('.faq-heading').nextElementSibling;

    if (!panel || !panel.classList.contains('details')) {
      console.warn('Panel not found for trigger:', btn);
      return;
    }

    // Set initial state: collapsed by default
    btn.setAttribute('aria-expanded', 'false');
    panel.hidden = true;

    // Click handler to toggle panel
    btn.addEventListener('click', () => {
      const isOpen = btn.getAttribute('aria-expanded') === 'true';
      btn.setAttribute('aria-expanded', String(!isOpen));
      panel.hidden = isOpen;
    });

    // Keyboard handler: Escape key closes the panel (optional enhancement)
    btn.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') {
        const isOpen = btn.getAttribute('aria-expanded') === 'true';
        if (isOpen) {
          btn.setAttribute('aria-expanded', 'false');
          panel.hidden = true;
          btn.focus();
        }
      }
    });
  });
});
