const fs = require('fs');
const path = require('path');
const axeSource = require('axe-core').source;

async function runAccessibilityTest() {
  const browser = await chromium.launch();
  const page = await browser.newPage();

  // Load the HTML file
  const htmlPath = path.join(__dirname, 'index.html');
  const htmlContent = fs.readFileSync(htmlPath, 'utf-8');

  // Set viewport to a standard desktop size
  await page.setViewportSize({ width: 1280, height: 720 });

  // Load the HTML
  await page.setContent(htmlContent, { waitUntil: 'load' });

  // Inject and run axe
  await page.addInitScript(axeSource);
  const results = await page.evaluate(async () => {
    return await window.axe.run();
  });

  await browser.close();

  // Separate WCAG violations from best-practice violations
  const wcagViolations = results.violations.filter(v => !v.tags.includes('best-practice'));
  const bpViolations = results.violations.filter(v => v.tags.includes('best-practice'));

  // Format results
  const formattedResults = {
    wcag: wcagViolations.map(v => ({
      id: v.id,
      impact: v.impact,
      description: v.description,
      targets: v.nodes.map(n => n.target)
    })),
    bestPractice: bpViolations.map(v => ({
      id: v.id,
      targets: v.nodes.map(n => n.target)
    })),
    passes: results.passes.length,
    totalViolations: results.violations.length
  };

  console.log(JSON.stringify(formattedResults, null, 2));

  process.exit(wcagViolations.length > 0 ? 1 : 0);
}

runAccessibilityTest().catch(err => {
  console.error('Test error:', err);
  process.exit(1);
});
